script:
app.beginUndoGroup("Glitch Block Tear");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.selectedLayers.length < 1) throw new Error("Select at least one layer.");
for (var i = 0; i < comp.selectedLayers.length; i++) {
  var layer = comp.selectedLayers[i];
  var effects = layer.property("ADBE Effect Parade");
  var posterize = effects.addProperty("ADBE Posterize Time");
  posterize.property("ADBE Posterize Time-0001").setValue(12);
  var tear = effects.addProperty("ADBE Slider Control");
  tear.name = "Tear Amount";
  tear.property(1).setValue(40);
  var displace = effects.addProperty("ADBE Turbulent Displace");
  displace.property("ADBE Turbulent Displace-0001").setValue(10);
  displace.property("ADBE Turbulent Displace-0002").expression = 'effect("Tear Amount")("Slider")';
  displace.property("ADBE Turbulent Displace-0003").setValue(8);
  displace.property("ADBE Turbulent Displace-0005").setValue(2);
  displace.property("ADBE Turbulent Displace-0012").setValue(3);
  displace.property("ADBE Turbulent Displace-0006").expression = "time * 400";
}
app.endUndoGroup();
